    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof decideProcurementRequest>>, TError,DecideProcurementRequestMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof decideProcurementRequest>>, TError,DecideProcurementRequestMutationVariables, TContext> => {

const mutationKey = getDecideProcurementRequestMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof decideProcurementRequest>>, DecideProcurementRequestMutationVariables> = (props) => {
          const {requestId,data} = props ?? {};

          return  decideProcurementRequest(requestId,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type DecideProcurementRequestMutationResult = NonNullable<Awaited<ReturnType<typeof decideProcurementRequest>>>
    export type DecideProcurementRequestMutationBody = BodyType<ProcurementDecisionInput>
    export type DecideProcurementRequestMutationError = ErrorType<void>
    export type DecideProcurementRequestMutationVariables = {requestId: number;data: BodyType<ProcurementDecisionInput>}

    /**
 * @summary Approve or reject a supplier offer
 */
export const useDecideProcurementRequest = <TError = ErrorType<void>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof decideProcurementRequest>>, TError,DecideProcurementRequestMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof decideProcurementRequest>>,
        TError,
        DecideProcurementRequestMutationVariables,
        TContext
      > => {
      return useMutation(getDecideProcurementRequestMutationOptions(options));
    }

